package com.discover.app.billing.repository; import com.discover.app.billing.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface CancellationRequestRepository extends JpaRepository<InvoiceCancellationRequest,Long> { boolean existsByInvoiceIdAndStatus(Long invoiceId,CancellationRequestStatus status); @Query("select r from InvoiceCancellationRequest r join fetch r.invoice i join fetch i.studentEnrollment e join fetch e.student s where r.status=:status order by r.createdAt asc, r.id asc") List<InvoiceCancellationRequest> findDetailedByStatus(@Param("status") CancellationRequestStatus status); @Query("select r from InvoiceCancellationRequest r join fetch r.invoice i join fetch i.studentEnrollment e join fetch e.student s order by r.createdAt desc, r.id desc") List<InvoiceCancellationRequest> findAllDetailed(); @Query("select r from InvoiceCancellationRequest r join fetch r.invoice i where r.id=:id") Optional<InvoiceCancellationRequest> findDetailedById(@Param("id") Long id); }
